// Program tạo ra theo pha hâm nền: node bgphase.mjs <repo> <dist>
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const repo = process.argv[2], dist = process.argv[3];
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
const srv = await lib.serveDir(dist);
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const { page } = await lib.openApp(browser, srv.url + '?perf&lightsets=bg', { width: 1920, height: 1080 });
try {
  await page.evaluate(() => { const d = window.__app.dayNight; d.target = d.night = 0.5; });
  // ghi program mới mỗi khung kèm pha
  await page.evaluate(() => {
    const A = window.__app, P = A.renderer.info.programs; window.__log = []; let n = P.length;
    const f = () => { const w = window.__warm; const tag = w ? `${w.sets[w.si].set}/p${w.phase}` : 'xong'; for (; n < P.length; n++) window.__log.push([tag, P[n].name, P[n].cacheKey]); if (A.lights.ready.night && !w) return; requestAnimationFrame(f); };
    requestAnimationFrame(f);
  });
  await page.waitForFunction(() => window.__app.lights.ready.night, null, { timeout: 180000, polling: 200 });
  await lib.frames(page, 5);
  const log = await page.evaluate(() => window.__log);
  const by = {}; for (const [t] of log) by[t] = (by[t] || 0) + 1;
  console.log('program mới theo pha:', JSON.stringify(by));
  const compiled = log.filter((x) => x[0].endsWith('/p0'));
  for (const tag of Object.keys(by).filter((t) => !t.endsWith('/p0'))) {
    console.log('== ' + tag);
    for (const [, name, key] of log.filter((x) => x[0] === tag).slice(0, 8)) {
      const parts = key.split(','); let best = null, bd = 1e9;
      for (const [, n2, k2] of compiled) { if (n2 !== name) continue; const p2 = k2.split(','); if (p2.length !== parts.length) continue; const diff = []; for (let i = 0; i < parts.length; i++) if (parts[i] !== p2[i]) diff.push(`${i}:${p2[i]}→${parts[i]}`); if (diff.length < bd) { bd = diff.length; best = diff; } }
      console.log(`  ${name} khác ${bd}: ${best ? best.slice(0, 10).join(' ') : '-'} | ${key.slice(0, 40)}…${key.slice(-110)}`);
    }
  }
} finally { await browser.close(); srv.close(); }

