// Biên dịch song song có thật không: node parcomp.mjs <repo> <dist>
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const repo = process.argv[2], dist = process.argv[3];
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
const srv = await lib.serveDir(dist);
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const { page } = await lib.openApp(browser, srv.url + '?perf', { width: 1920, height: 1080 });
try {
  await lib.frames(page, 30);
  for (const N of [1, 4]) for (const kind of ['standard', 'standard+3pt']) {
    const r = await page.evaluate(async ({ N, kind }) => {
      const A = window.__app, T = A.THREE, R = A.renderer;
      const sc = new T.Scene(); sc.add(new T.HemisphereLight()); const dl = new T.DirectionalLight(); dl.castShadow = true; sc.add(dl);
      if (kind.includes('3pt')) for (let i = 0; i < 3; i++) sc.add(new T.PointLight());
      const g = new T.Object3D();
      for (let i = 0; i < N; i++) { const m = new T.MeshStandardMaterial(); m.customProgramCacheKey = () => 'x' + Math.random(); g.add(new T.Mesh(new T.BoxGeometry(), m)); }
      sc.fog = A.scene.fog; sc.environment = A.scene.environment;
      const P = R.info.programs, before = P.length;
      const frame = () => new Promise((ok) => requestAnimationFrame(() => ok(performance.now())));
      await frame(); let t = await frame(); const base = []; for (let i = 0; i < 5; i++) { const t2 = await frame(); base.push(t2 - t); t = t2; }
      const t0 = performance.now(); R.compile(g, A.camera, sc); const tc = performance.now() - t0;
      const nu = P.slice(before); const fr = []; let t1 = performance.now(); let readyAt = -1;
      for (let i = 0; i < 60; i++) { const t2 = await frame(); fr.push(Math.round(t2 - t1)); t1 = t2; if (readyAt < 0 && nu.every((p) => p.isReady())) { readyAt = Math.round(t2 - t0); } if (readyAt >= 0 && i > 10) break; }
      return { N, kind, newPrograms: nu.length, compileJs: +tc.toFixed(1), baseFrame: Math.round(base.sort((a, b) => a - b)[2]), framesAfter: fr.slice(0, 12), readyAfterMs: readyAt };
    }, { N, kind });
    console.log(JSON.stringify(r));
  }
} finally { await browser.close(); srv.close(); }

