151	/* Vẽ thật một nhóm object với một bộ đèn, ngoài màn hình (trước lượt vẽ thật của khung, cùng lời gọi). Cần vì program "xong" (isReady) mới là
152	   xong phần link: trình điều khiển D3D còn dịch tiếp lúc vẽ lần đầu với từng định dạng đích (đo Intel Arc, chưa có bước này: lần đầu sang 'night'
153	   khựng 0,7 s dù +0 program; lần đầu sang 'day' gần 1 s). Vẽ vào scene riêng (w.draw) có children = đèn của bộ + các object của nhóm:
154	   parent của object không đổi (matrixWorld đã tính ở khung trước, tắt matrixWorldAutoUpdate), trạng thái đèn của cảnh thật không bị đụng.
155	   Ba đích như khung thật: canvas (biến thể tone mapping; cắt kéo 1×1, khung thật xoá cả canvas ngay sau), render target 1×1 HalfFloat
156	   (định dạng của composer ban đêm), 1×1 RGBA8 (định dạng phản chiếu mặt nước). Lượt bóng (MeshDepthMaterial) chỉ vẽ ở đích đầu và chỉ khi
157	   khung thật cũng vẽ lại bóng ngay sau (autoUpdate): không thì shadow map đang dùng bị ghi đè bằng bóng của riêng nhóm này.
158	   Nước: bỏ qua onBeforeRender (không vẽ lại phản chiếu thật). */
159	function drawChunk(w: Warm, si: number, canvasOnly: boolean) {
160	  const kids = w.kids, ls = w.sets[si].lights, sv = w.saved, sm = renderer.shadowMap;
161	  kids.length = 0;
162	  for (let k = 0; k < ls.length; k++) { kids.push(ls[k]); sv[k] = ls[k].visible ? 1 : 0; ls[k].visible = true; }
163	  for (let k = w.from; k < w.to; k++) {
164	    const o = w.objs[k], im = o as THREE.InstancedMesh, j = ls.length + k - w.from;
165	    sv[j] = (o.visible ? 1 : 0) | (o.frustumCulled ? 2 : 0) | (im.isInstancedMesh && im.count === 0 ? 4 : 0);
166	    o.visible = true; o.frustumCulled = false; if (sv[j] & 4) im.count = 1;
167	    kids.push(o);
168	  }
169	  const ob = water.onBeforeRender, au = sm.autoUpdate, nu = sm.needsUpdate, c = renderer.info.render.calls, t = renderer.info.render.triangles;
170	  water.onBeforeRender = noop;
171	  w.draw.fog = scene.fog; w.draw.environment = scene.environment; w.draw.environmentRotation.copy(scene.environmentRotation);   // cùng key fog / envMap
172	  sm.autoUpdate = false; sm.needsUpdate = au;
173	  renderer.setRenderTarget(null); renderer.setScissorTest(true); renderer.setScissor(0, 0, 1, 1);
174	  renderer.render(w.draw, camera);
175	  renderer.setScissorTest(false); sm.needsUpdate = false;
176	  if (!canvasOnly) for (const rt of w.rts) { renderer.setRenderTarget(rt); renderer.render(w.draw, camera); }
177	  sm.autoUpdate = au; sm.needsUpdate = nu; water.onBeforeRender = ob;
178	  renderer.info.render.calls = c; renderer.info.render.triangles = t;   // không tính vào lệnh vẽ của khung (HUD, test)
179	  for (let k = 0; k < ls.length; k++) ls[k].visible = sv[k] === 1;
180	  for (let k = w.from; k < w.to; k++) {
181	    const o = w.objs[k], j = ls.length + k - w.from;
182	    o.visible = (sv[j] & 1) !== 0; o.frustumCulled = (sv[j] & 2) !== 0; if (sv[j] & 4) (o as THREE.InstancedMesh).count = 0;
183	  }
184	  kids.length = 0;
185	}
186	const noop = () => {};
187	/* Mỗi khung, trước lượt vẽ thật (sau quality.update: biết khung này có vẽ lại bóng không). Ba pha cho từng bộ day rồi night:
188	   compile (ngân sách) → chờ mọi program mới isReady → vẽ thật từng nhóm (ngân sách) ⇒ ready[bộ].
189	   Pha vẽ của night: mỗi nhóm vẽ night rồi vẽ day một lần (chỉ canvas): khung 'day' đầu tiên sau đêm, lượt bóng còn mang trạng thái đèn night
190	   (three vẽ bóng trước khi cập nhật đèn) ⇒ biến thể MeshDepthMaterial đó được biên dịch + vẽ sẵn ở đây. */
191	export function warmLightSets() {
192	  if (warmDone) return;
193	  if (lightState.mode !== 'bg') { warmDone = true; return; }
194	  if (!warm) {
195	    if (!renderer.extensions.has('KHR_parallel_shader_compile')) { lightState.mode = 'off'; warmDone = true; return; }
196	    warm = warmInit();
197	  }
198	  const w = warm, n = w.objs.length, t0 = performance.now(), rt = renderer.getRenderTarget(), set = w.sets[w.si].set;
199	  if (w.phase === 0) {   // biên dịch nền: giữ tối đa lightWarmPrograms program đang dịch dở (đo Intel Arc: dồn nhiều ⇒ khung 100–600 ms)
200	    while (w.pi < w.pending.length && w.pending[w.pi].isReady()) w.pi++;   // COMPLETION_STATUS_KHR: không chặn
201	    const progs = renderer.info.programs;
202	    w.scene.fog = scene.fog; w.scene.environment = scene.environment; w.scene.environmentRotation.copy(scene.environmentRotation);   // cùng key fog / envMap với cảnh thật
203	    let clipSet = false;   // khung thật vừa vẽ đã đổi trạng thái cắt ⇒ đặt lại ở lần compile đầu của mỗi lời gọi
204	    while (w.i < n && w.pending.length - w.pi < CONFIG.perf.lightWarmPrograms && performance.now() - t0 < CONFIG.perf.lightWarmMs) {
205	      while (w.i >= w.clips[w.ci].end) { w.ci++; clipSet = false; }
206	      if (!clipSet) { setClip(w, w.ci); clipSet = true; }
207	      w.from = w.i; w.to = Math.min(w.i + CHUNK, w.clips[w.ci].end);
208	      const before = progs.length;
209	      renderer.setRenderTarget(null); renderer.compile(w.proxy, camera, w.scene);
210	      renderer.setRenderTarget(composer.readBuffer); renderer.compile(w.proxy, camera, w.scene);
211	      for (let k = before; k < progs.length; k++) w.pending.push(progs[k] as unknown as Ready);
212	      for (let k = w.from; k < w.to; k++) {
213	        const m = (w.objs[k] as THREE.Mesh).material;
214	        if (Array.isArray(m)) for (const x of m) x.needsUpdate = true; else m.needsUpdate = true;
215	      }
216	      w.i = w.to;
217	    }
218	    renderer.setRenderTarget(rt);
219	    if (w.i < n || w.pi < w.pending.length) return;
220	    w.phase = 2; w.i = 0;   // mọi program của bộ đã link xong
221	    w.from = w.to = 0; drawChunk(w, w.si, true);   // nhóm rỗng: đặt trạng thái đèn của scene vẽ = bộ này (lượt bóng nhóm đầu đọc nó)
222	  }
223	  while (w.i < n && performance.now() - t0 < CONFIG.perf.lightWarmMs) {   // vẽ thật
224	    w.from = w.i; w.to = Math.min(w.i + DRAW_CHUNK, n);
225	    drawChunk(w, w.si, false);
226	    if (set === 'night') drawChunk(w, 0, true);   // sets[0] là day
227	    w.i = w.to;
228	  }
229	  renderer.setRenderTarget(rt);
230	  if (w.i < n) return;
231	  lightState.ready[set] = true;
232	  if (++w.si < w.sets.length) { w.phase = 0; w.i = 0; w.ci = 0; w.pending.length = 0; w.pi = 0; return; }
233	  w.clipRT.dispose(); w.clipMesh.geometry.dispose(); for (const c of w.clips) c.mat.dispose(); for (const r of w.rts) r.dispose();
234	  warm = null; warmDone = true;
235	}
